import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import {
  validateStatement,
  financialLine,
  type FinancialStatement,
} from "./financial.ts";
import { statementLines, yearMonths } from "./prime-reports.ts";
import { statementCsvRows } from "./financial-export.ts";

// Generated by backend statements(): published Obex Jan–Sep headlines plus
// synthetic September/October allocation publications from backend unit fixtures.
const fixture = JSON.parse(
  readFileSync(
    new URL("./fixtures/monthly-statement.json", import.meta.url),
    "utf8",
  ),
);

test("GAR is only shown for Skybase in statements and CSVs", () => {
  for (const prime of [
    "spark",
    "grove",
    "obex",
    "keel",
    "skybase",
    "osero",
  ] as const) {
    for (const scope of ["individual", "group"] as const) {
      assert.equal(
        statementLines(prime, scope).some((l) => l.id === "gar"),
        prime === "skybase",
      );
      const csv = statementCsvRows(
        prime,
        scope,
        2026,
        "2026-10",
        yearMonths(2026),
      );
      assert.equal(
        csv.some((r) => r[2] === "Governance accessibility rewards (GAR)"),
        prime === "skybase",
      );
    }
  }
  assert.equal(
    statementLines(null, "combined").some((l) => l.id === "gar"),
    false,
  );
});

test("monthly sources populate January–August without daily publications and bind demand/DR", () => {
  const report = validateStatement(fixture, "obex", 2026);
  assert.equal(report.periods[0].financial_revision, null);
  assert.ok(report.periods[0].monthly_revision);
  assert.equal(
    financialLine(report, "dr")?.values["2026-01"].status,
    "available",
  );
  assert.equal(
    financialLine(report, "demand")?.values["2026-08"].status,
    "available",
  );
  assert.equal(
    financialLine(report, "obex-maple")?.values["2026-09"].value,
    "100",
  );
  assert.equal(financialLine(report, "dr")?.values["2026-10"].value, null);
  assert.equal(financialLine(report, "dr")?.total.value, null);
  const rows = statementCsvRows(
    "obex",
    "individual",
    2026,
    "2026-10",
    yearMonths(2026, new Date("2027-01-10")),
    report,
  );
  const dr = rows.find((r) => r[2] === "Distribution rewards (DR)")!;
  assert.equal(dr[3], financialLine(report, "dr")?.values["2026-01"].value);
  assert.equal(dr[10], financialLine(report, "dr")?.values["2026-08"].value);
  assert.equal(dr[12], "TBD");
  assert.equal(dr[15], "Partial");
  assert.equal(dr[19], report.selection);
  assert.equal(
    JSON.parse(dr[21] as string)["2026-01"],
    report.periods[0].monthly_revision,
  );
  assert.ok(rows.every((r) => r.length === rows[0].length));
});

test("rejects missing, mismatched, future and unbacked monthly provenance", () => {
  const mutators: ((v: FinancialStatement) => void)[] = [
    (v) => {
      financialLine(v, "obex-maple")!.values["2026-09"].source_ref =
        v.periods[8].monthly_revision!;
    },
    (v) => {
      v.periods[0].monthly_revision = null;
    },
    (v) => {
      v.periods[0].monthly_revision = v.periods[1].monthly_revision;
    },
    (v) => {
      delete v.source_manifest[v.periods[0].monthly_revision!];
    },
    (v) => {
      v.source_manifest[v.periods[0].monthly_revision!].currency = "DAI";
    },
    (v) => {
      v.source_manifest[v.periods[0].monthly_revision!].path =
        "reports/spark/2026-01/summary.md";
    },
    (v) => {
      financialLine(v, "dr")!.values["2026-01"].source_ref =
        v.periods[1].monthly_revision!;
    },
    (v) => {
      delete financialLine(v, "dr")!.values["2026-01"].source_ref;
    },
    (v) => {
      v.periods[10].monthly_revision = v.periods[0].monthly_revision;
    },
  ];
  for (const mutate of mutators) {
    const bad = structuredClone(fixture);
    mutate(bad);
    assert.throws(() => validateStatement(bad, "obex", 2026));
  }
});
